// Writes client/operations.generated.ts: operationId -> { method, path } from docs/openapi.json (do not edit the output).
import { readFileSync, writeFileSync } from 'node:fs';
const spec = JSON.parse(readFileSync(new URL('../../docs/openapi.json', import.meta.url), 'utf8'));
const out = {};
for (const [path, item] of Object.entries(spec.paths)) {
  for (const method of ['get', 'post', 'put', 'patch', 'delete']) {
    const op = item[method];
    if (op) out[op.operationId] = { method, path };
  }
}
const body = Object.keys(out).sort().map((k) => `  ${k}: { method: '${out[k].method}', path: '${out[k].path}' },`).join('\n');
writeFileSync(new URL('../client/operations.generated.ts', import.meta.url), `// GENERATED by scripts/gen-operations.mjs — do not edit.\nexport const OPERATIONS = {\n${body}\n} as const;\n`);
console.log(`wrote ${Object.keys(out).length} operations`);
